class Worker:
    id: str
    enabled: bool
    model_key: str | None
    endpoint: str | None
    capabilities: tuple[str, ...]
    failover_order: int | None
    role: str = "coder"
    priority: int = 100
    notes: str = ""

    def status(self) -> str:
        if not self.enabled:
            return "unavailable"
        if not self.model_key:
            return "unconfigured"
        return "healthy"


class WorkerRegistry:
